<?php
require __DIR__ . '/admin_common.php';
require __DIR__ . '/admin_layout.php';
admin_start('Products', 'products', $config);
$views = ['all' => 'All products', 'live' => 'Live', 'hidden' => 'Hidden', 'archived' => 'Archived'];
?>
<section class="panel" id="products"><div class="section-title"><div><div class="eyebrow">Catalogue</div><h2><?= $editingProduct ? 'Edit product.' : 'Add a product.' ?></h2></div><p>Manage what customers can see without losing your product history.</p></div><?php if ($editingProduct && product_state($editingProduct) === 'archived'): ?><div class="notice">This product is permanently archived. You can update its record, but it cannot be moved back to Live.</div><?php endif; ?><form class="product-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><input type="hidden" name="product_id" value="<?=admin_h($editingProduct['id'] ?? '')?>"><div class="field"><label>Product name</label><input name="name" maxlength="160" value="<?=admin_h($editingProduct['name'] ?? '')?>" required></div><div class="field"><label>Price in NGN</label><input name="price" type="number" min="0.01" step=".01" value="<?= $editingProduct ? admin_h(number_format($editingProduct['price_kobo'] / 100, 2, '.', '')) : '' ?>" required></div><div class="field full"><label>Description</label><textarea name="description" maxlength="5000" placeholder="What does this fragrance feel like?"><?=admin_h($editingProduct['description'] ?? '')?></textarea></div><div class="field"><label>Product image upload</label><input name="image" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP. Maximum 5MB.</small><?php if (!empty($editingProduct['image_url'])): ?><small>Current image remains unless replaced.</small><?php endif; ?></div><div class="field"><label>Image URL fallback</label><input name="image_url" type="url" maxlength="500" placeholder="https://..." value="<?=admin_h($editingProduct['image_url'] ?? '')?>"><small>An uploaded file takes priority.</small></div><div class="field"><label>Stock</label><input name="stock" type="number" min="0" value="<?=($editingProduct && $editingProduct['stock'] !== null) ? admin_h($editingProduct['stock']) : ''?>" placeholder="Blank = unlimited"></div><div class="field full form-actions"><button class="primary" name="save" value="1"><?= $editingProduct ? 'Save product changes' : 'Publish product' ?></button><?php if ($editingProduct): ?><a class="cancel" href="/admin/products">Cancel edit</a><?php endif; ?></div></form></section>
<section class="panel"><div class="section-title"><div><div class="eyebrow">Product visibility</div><h2>Choose what is live.</h2></div><p>Hidden products can return to Live. Archived products are permanent and can never be published again.</p></div><div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:26px"><?php foreach ($views as $key => $label): $tabStyle = $productView === $key ? 'background:var(--ink);color:var(--cream)' : 'background:#fff;color:var(--ink)'; ?><a href="/admin/products?view=<?=$key?>" style="display:inline-flex;gap:8px;align-items:center;padding:10px 13px;border:1px solid var(--line);border-radius:999px;text-decoration:none;font-size:11px;<?=$tabStyle?>"><?=$label?> <span><?=count(array_filter($products, fn($product) => $key === 'all' || product_state($product) === $key))?></span></a><?php endforeach; ?></div><div class="product-list"><?php if (!$visibleProducts): ?><p style="color:var(--muted)">There are no products in this view.</p><?php endif; ?><?php foreach ($visibleProducts as $p): $state = product_state($p); ?><div class="product-row"><?php if ($p['image_url']): ?><a href="<?=admin_h($p['image_url'])?>" target="_blank" rel="noreferrer" title="Open full-size image"><img class="thumb" src="<?=admin_h($p['image_url'])?>" alt="<?=admin_h($p['name'])?>"></a><?php else: ?><span class="thumb-placeholder">BL</span><?php endif; ?><div><h3><?=admin_h($p['name'])?></h3><p><strong style="color:var(--<?=$state === 'live' ? 'gold' : ($state === 'hidden' ? 'rose' : 'muted')?>)"><?=admin_h(ucfirst($state))?></strong> · <?= $p['stock'] === null ? 'Unlimited stock' : (int) $p['stock'] . ' in stock' ?></p><div class="row-actions"><a href="/admin/products?view=<?=$productView?>&amp;edit=<?= (int) $p['id'] ?>">Edit</a><?php if ($state === 'live'): ?><form method="post"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><button name="del" value="<?= (int) $p['id'] ?>">Move to Hidden</button></form><form method="post" onsubmit="return confirm('Archive this product permanently? It can never return to Live.');"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><button name="archive" value="<?= (int) $p['id'] ?>">Archive permanently</button></form><?php elseif ($state === 'hidden'): ?><form method="post"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><button name="restore" value="<?= (int) $p['id'] ?>">Move to Live</button></form><form method="post" onsubmit="return confirm('Archive this product permanently? It can never return to Live.');"><input type="hidden" name="csrf" value="<?=admin_h($csrfToken)?>"><button name="archive" value="<?= (int) $p['id'] ?>">Archive permanently</button></form><?php else: ?><span style="color:var(--muted);font-size:11px">Permanently archived</span><?php endif; ?></div></div><div class="product-row-meta"><strong>₦<?=number_format($p['price_kobo'] / 100, 2)?></strong><span><?=admin_h($state === 'archived' ? 'History only' : ($state === 'live' ? 'Visible' : 'Not visible'))?></span></div></div><?php endforeach; ?></div></section>
<?php admin_end(); ?>
